CREATE VIEW PS_ZZ_DSTNCT_DEPT (SETID, DEPTID, TREE_NODE_NUM,
 TREE_NODE_NUM_END) AS SELECT  SETID,  DEPTID,  TREE_NODE_NUM, 
 TREE_NODE_NUM_END  FROM PS_TRN_DPTSCRTY_VW  GROUP BY SETID, DEPTID
,TREE_NODE_NUM,  TREE_NODE_NUM_END
